REPOSITORY_SHA = "a" * 40
GO_VERSION = "go version go1.26.0 windows/amd64"
PACKAGES = ["example/heavy", 'example/quo"te']
STDOUT_SENTINEL = b'{"Action":"output","Output":"CHILD-STDOUT-SENTINEL \\u00e9\\n"}\r\n\x00tail'
